#!/usr/bin/env node
// GENERATED by scripts/gen/build.mjs from gen/tools/check-boundaries.mjs - edit the sources, not this file.
// Checks module boundaries in a .NET modular monolith: modules may depend on each other only through ".Contracts" projects.
// Heuristic (project files and using directives). Reports candidates; confirm each in context.
// Usage: node check-boundaries.mjs [path] [--json] [--strict]    (--strict: exit 1 when any HIGH finding exists)
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve } from "node:path";
const SKIP_DIRS = new Set([
  "bin",
  "obj",
  "node_modules",
  ".git",
  ".vs",
  "TestResults",
  "artifacts",
]);
const ROLE_SUFFIX =
  /\.(Contracts|Tests|UnitTests|IntegrationTests|Infrastructure|Domain|Application|Api|Endpoints|Migrations)$/i;
const SHARED_NAME = /(^|\.)(Shared|SharedKernel|BuildingBlocks|Common|Kernel)(\.|$)/i;
// Composition roots reference every module's implementation by design, so they belong to no module.
const HOST_NAME = /(^|\.)(Host|WebHost|AppHost|Bootstrapper)(\.|$)/i;
// Vendor/framework namespace roots: never a module, even when a module shares a segment name (Microsoft.AspNetCore.Identity vs module Identity).
const VENDOR_ROOTS = new Set([
  "System",
  "Microsoft",
  "Azure",
  "Amazon",
  "Google",
  "Newtonsoft",
  "Serilog",
  "MassTransit",
  "MediatR",
  "FluentValidation",
  "Xunit",
  "NUnit",
  "Moq",
  "NSubstitute",
  "Dapper",
  "Polly",
  "OpenTelemetry",
]);
const posix = (p) => p.split("\\").join("/");

function* walkFiles(dir, depth = 0) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name) && depth < 24) yield* walkFiles(join(dir, e.name), depth + 1);
    } else yield join(dir, e.name);
  }
}

// Target framework set in the nearest Directory.Build.props above the project (stops at the repo root).
function inheritedTfm(file, root) {
  for (let d = dirname(file); ; d = dirname(d)) {
    const t = tryRead(join(d, "Directory.Build.props"));
    const m = t && /<TargetFrameworks?>([^<$]+)</i.exec(t);
    if (m) return m[1];
    if (d === root || d === dirname(d)) return undefined;
  }
}

function readProjects(root) {
  const projects = [];
  for (const file of walkFiles(root)) {
    if (!file.endsWith(".csproj")) continue;
    // XML comments are ignored: a commented-out reference is not a reference.
    const text = readFileSync(file, "utf8").replace(/<!--[\s\S]*?-->/g, " ");
    const all = (re) => [...text.matchAll(re)].map((m) => m[1]);
    const name = basename(file, ".csproj");
    projects.push({
      name,
      file,
      dir: dirname(file),
      rel: posix(relative(root, file)),
      refs: all(/<ProjectReference\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi)
        .map((r) =>
          r.replace(
            /\$\((MSBuildThisFileDirectory|MSBuildProjectDirectory)\)[\\/]?/i,
            `${dirname(file)}/`,
          ),
        )
        .filter((r) => !r.includes("$("))
        .map((r) => resolve(dirname(file), r.split("\\").join("/"))),
      packages: all(/<PackageReference\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi),
      frameworks: all(/<FrameworkReference\s[^>]*?Include\s*=\s*"([^"]+)"/gi),
      ivt: all(/<InternalsVisibleTo\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi).map((n) =>
        n.split(",")[0].trim(),
      ),
      tfms: (/<TargetFrameworks?>([^<]+)</i.exec(text)?.[1] ?? inheritedTfm(file, root) ?? "")
        .split(";")
        .map((t) => t.trim())
        .filter(Boolean),
      isTest:
        /<IsTestProject>\s*true/i.test(text) ||
        /Microsoft\.NET\.Test\.Sdk/.test(text) ||
        /\.(Unit|Integration)?Tests?$/i.test(name),
    });
  }
  return detectModules(projects, root);
}

function detectModules(projects, root) {
  let config = {};
  try {
    config = JSON.parse(readFileSync(join(root, "modules.json"), "utf8"));
  } catch {
    // no config: use conventions
  }
  const stripRoles = (name) => {
    let base = name;
    for (let m = ROLE_SUFFIX.exec(base); m; m = ROLE_SUFFIX.exec(base))
      base = base.slice(0, m.index);
    return base || name;
  };
  const bases = projects.map((p) => stripRoles(p.name));
  const multi = bases.filter((b) => b.includes("."));
  const first = multi.map((b) => b.split(".")[0]);
  const top = [...new Set(first)]
    .map((s) => [s, first.filter((x) => x === s).length])
    .sort((a, b) => b[1] - a[1])[0];
  const prefix = top && multi.length >= 3 && top[1] / bases.length >= 0.8 ? `${top[0]}.` : "";
  // Path-boundary prefix match; the longest matching prefix wins (so "src/Orders" does not swallow "src/Orders2").
  const under = (rel, x) => {
    const base = x.replace(/\/+$/, "");
    return rel === base || rel.startsWith(`${base}/`);
  };
  const configured = (rel) => {
    const hits = [
      ...Object.entries(config.modules ?? {}).flatMap(([module, paths]) =>
        paths.filter((x) => under(rel, x)).map((x) => ({ module, len: x.length })),
      ),
      ...(config.shared ?? [])
        .filter((x) => under(rel, x))
        .map((x) => ({ module: null, len: x.length })),
    ].sort((a, b) => b.len - a.len);
    return hits[0];
  };

  // When the repository clearly organises modules as Modules/<Name>/ (at least 4 projects), everything outside that folder
  // (hosts, building blocks, tools, cross-cutting tests) belongs to no module: a product or company name is not a module.
  const pathHit = (p) => /(?:^|\/)[Mm]odules\/([^/]+)\//.exec(`/${p.rel}`);
  const pathMode = !config.modules && projects.filter((p) => pathHit(p)).length >= 4;
  const fixed = new Set(); // projects whose module came from modules.json or the Modules/<Name> folder

  for (const [i, p] of projects.entries()) {
    let module;
    const hit = configured(p.rel);
    const m = pathHit(p);
    if (hit) module = hit.module;
    else if (m) module = m[1];
    else if (pathMode && !p.isTest) module = null; // tests fall through to their name, then to what they reference
    else if (SHARED_NAME.test(bases[i]) || HOST_NAME.test(bases[i])) module = null;
    // Acme.Api / Acme.Web: nothing left after the company prefix, so it is the host, not a module named "Acme".
    else if (prefix && bases[i] === prefix.slice(0, -1)) module = null;
    else module = prefix && bases[i].startsWith(prefix) ? bases[i].slice(prefix.length) : bases[i];
    if (hit || m) fixed.add(p);
    p.module = module;
    // "Zivex.Modules.Contracts" is the implementation of a module that is called Contracts; "Quotes.Contracts" is a contract project.
    const named =
      /\.Contracts$/i.test(p.name) &&
      !(module === "Contracts" && !/\.Contracts\.Contracts$/i.test(p.name));
    p.role = p.isTest ? "test" : named ? "contracts" : "impl";
    if (module === null && !p.isTest) p.role = "shared";
  }

  // A test project belongs to the module its name points at; otherwise to the one module it references. One that references
  // several modules (architecture, integration, security suites) is cross-cutting and belongs to none.
  const byPath = new Map(projects.map((p) => [resolve(p.file), p]));
  const known = new Set(projects.filter((x) => !x.isTest && x.module).map((x) => x.module));
  for (const p of projects.filter((x) => x.isTest && !fixed.has(x))) {
    if (p.module && known.has(p.module)) continue; // the name points at a real module (Orders.Tests -> Orders): keep it
    const mods = new Set(
      p.refs
        .map((r) => byPath.get(r))
        .filter((t) => t && !t.isTest && t.module)
        .map((t) => t.module),
    );
    if (mods.size === 1) p.module = [...mods][0];
    else if (mods.size > 1 || pathMode) p.module = null;
  }
  return projects;
}

const projectOf = (projects, file) =>
  projects
    .filter((p) => resolve(file).startsWith(`${p.dir}${process.platform === "win32" ? "\\" : "/"}`))
    .sort((a, b) => b.dir.length - a.dir.length)[0];
const byFile = (projects) => new Map(projects.map((p) => [resolve(p.file), p]));
const moduleNames = (projects) =>
  [...new Set(projects.map((p) => p.module).filter(Boolean))].sort();
function tryRead(path) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return undefined;
  }
}

// Blank out /* ... */ comments but keep the newlines, so line numbers stay right.
const stripBlockComments = (text) =>
  text.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " "));

const args = process.argv.slice(2);
const root = resolve(args.find((a) => !a.startsWith("--")) ?? process.cwd());
const json = args.includes("--json");
const projects = readProjects(root);
const byPath = byFile(projects);
const modules = moduleNames(projects);
const findings = [];
const add = (id, level, file, line, msg, fix) => findings.push({ id, level, file, line, msg, fix });
const rel = (p) => posix(relative(root, p));
const SHARED_OK = (p) => p.role === "shared";

if (modules.length < 2) {
  if (json) console.log(JSON.stringify({ modules, findings: [] }, null, 2));
  else
    console.log(
      `${modules.length} module(s) detected (${modules.join(", ") || "none"}): nothing to check across modules. Add modules.json to describe modules explicitly.`,
    );
  process.exit(0);
}

// BND001/BND002: project references across modules must target the other module's Contracts project.
const edges = new Map();
for (const p of projects) {
  for (const target of p.refs) {
    const t = byPath.get(target);
    if (!t || SHARED_OK(t) || SHARED_OK(p) || !p.module || !t.module || p.module === t.module)
      continue;
    if (p.role !== "test")
      (edges.get(p.module) ?? edges.set(p.module, new Set()).get(p.module)).add(t.module);
    if (t.role === "contracts") continue;
    if (p.role === "test")
      add(
        "BND002",
        "medium",
        p.rel,
        1,
        `Test project of ${p.module} references ${t.name} (implementation of ${t.module})`,
        `Test against ${t.module}.Contracts or a fake; tests of one module should not depend on another module's internals.`,
      );
    else
      add(
        "BND001",
        "high",
        p.rel,
        1,
        `${p.name} (${p.module}) references ${t.name}, the implementation of module ${t.module}`,
        `Reference ${t.module}.Contracts only; if the needed type is missing, add it to the contract (see dotnet-module-contract).`,
      );
  }
}

// BND003: cycles between modules (even through contracts they make modules inseparable).
// Tarjan's strongly connected components: linear time, one finding per group of modules that depend on each other.
{
  let counter = 0;
  const index = new Map();
  const low = new Map();
  const onStack = new Set();
  const stack = [];
  const strong = (v) => {
    index.set(v, counter);
    low.set(v, counter++);
    stack.push(v);
    onStack.add(v);
    for (const w of edges.get(v) ?? []) {
      if (!index.has(w)) {
        strong(w);
        low.set(v, Math.min(low.get(v), low.get(w)));
      } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
    }
    if (low.get(v) === index.get(v)) {
      const group = [];
      let w;
      do {
        w = stack.pop();
        onStack.delete(w);
        group.push(w);
      } while (w !== v);
      if (group.length > 1)
        add(
          "BND003",
          "medium",
          ".",
          1,
          `Modules depend on each other in a cycle: ${group.sort().join(" <-> ")}`,
          "Break the cycle: invert one dependency with an integration event, or move the shared concept into a contract both can use.",
        );
    }
  };
  for (const v of [...edges.keys()].sort()) if (!index.has(v)) strong(v);
}

// BND005: contracts must stay free of implementation and framework-heavy dependencies.
for (const p of projects.filter((x) => x.role === "contracts")) {
  for (const target of p.refs) {
    const t = byPath.get(target);
    if (t && t.module === p.module && t.role === "impl")
      add(
        "BND005",
        "medium",
        p.rel,
        1,
        `${p.name} references its own implementation ${t.name}`,
        "Contracts must not depend on the implementation (it creates a cycle and leaks internals).",
      );
  }
  const heavy = p.packages
    .filter((n) =>
      /^Microsoft\.EntityFrameworkCore|^Microsoft\.AspNetCore|^MassTransit|^MediatR$/i.test(n),
    )
    .concat(p.frameworks.filter((n) => /AspNetCore/i.test(n)));
  if (heavy.length)
    add(
      "BND005",
      "medium",
      p.rel,
      1,
      `${p.name} depends on ${heavy.join(", ")}`,
      "Keep contracts to plain interfaces, records and events; no ORM or web types.",
    );
}

const underAny = (ns, names) => names.some((n) => ns === n || ns.startsWith(`${n}.`));
const sharedNames = projects.filter((p) => p.role === "shared").map((p) => p.name);
const implNames = new Map(
  modules.map((m) => [
    m,
    projects.filter((p) => p.module === m && p.role === "impl").map((p) => p.name),
  ]),
);
const contractNames = new Map(
  modules.map((m) => [
    m,
    projects.filter((p) => p.module === m && p.role === "contracts").map((p) => p.name),
  ]),
);

// Source scan: InternalsVisibleTo to another module, and using directives into another module's namespaces.
const ivtFinding = (p, name, file, line) => {
  const t = projects.find((x) => x.name === name);
  if (t && t.module && p.module && t.module !== p.module && t.role !== "test")
    add(
      "BND004",
      "high",
      file,
      line,
      `InternalsVisibleTo grants ${t.name} (module ${t.module}) access to ${p.module} internals`,
      "Remove it; expose what the other module needs through the contract.",
    );
};
for (const file of walkFiles(root)) {
  if (!file.endsWith(".cs")) continue;
  const p = projectOf(projects, file);
  if (!p || p.role === "test" || p.role === "shared" || !p.module) continue;
  const text = stripBlockComments(tryRead(file) ?? "");
  text.split("\n").forEach((line, i) => {
    if (line.trimStart().startsWith("//")) return;
    // [assembly: InternalsVisibleTo("Billing")], with a public key ("Billing, PublicKey=...") or a named argument (assemblyName: "Billing")
    const ivt = /InternalsVisibleTo\(\s*(?:assemblyName\s*:\s*)?"([^",]+)/.exec(line);
    if (ivt) ivtFinding(p, ivt[1].trim(), rel(file), i + 1);
    // using X.Y; / global using X.Y; / using static X.Y; / using Alias = X.Y.Z;
    const use = /^\s*(?:global\s+)?using\s+(?:static\s+)?(?:\w+\s*=\s*)?([\w.]+)\s*;/.exec(line);
    if (use && p.role !== "contracts") {
      const ns = use[1];
      if (VENDOR_ROOTS.has(ns.split(".")[0]) || underAny(ns, sharedNames)) return;
      // The namespace follows the project name (the .NET default): a using that starts with another module's implementation project
      // name, and not with one of its Contracts project names, reaches into that module.
      const other = modules.find(
        (m) =>
          m !== p.module &&
          underAny(ns, implNames.get(m) ?? []) &&
          !underAny(ns, contractNames.get(m) ?? []),
      );
      if (other)
        add(
          "BND006",
          "medium",
          rel(file),
          i + 1,
          `using ${ns} reaches into module ${other} outside its Contracts namespace`,
          `Use ${other}.Contracts types only.`,
        );
    }
  });
}
for (const p of projects) for (const name of p.ivt) ivtFinding(p, name, p.rel, 1);

// BND008: each module should explain itself to agents and humans.
for (const m of modules) {
  const dirs = projects.filter((p) => p.module === m && p.role === "impl").map((p) => p.dir);
  const candidates = dirs.flatMap((d) => [d, dirname(d)]);
  if (dirs.length && !candidates.some((d) => existsSync(join(d, "AGENTS.md"))))
    add(
      "BND008",
      "low",
      rel(dirs[0]),
      1,
      `Module ${m} has no AGENTS.md`,
      "Add one (purpose, contract, layout, rules, test command); dotnet-conventions-bootstrap can draft it.",
    );
}

const unique = [
  ...new Map(findings.map((f) => [`${f.id}|${f.file}|${f.line}|${f.msg}`, f])).values(),
];
const order = { high: 0, medium: 1, low: 2 };
unique.sort(
  (a, b) => order[a.level] - order[b.level] || a.file.localeCompare(b.file) || a.line - b.line,
);
if (json) console.log(JSON.stringify({ modules, findings: unique }, null, 2));
else {
  for (const f of unique)
    console.log(
      `${f.file}:${f.line}  ${f.level.toUpperCase()}  ${f.id}  ${f.msg}\n    fix: ${f.fix}`,
    );
  const n = (l) => unique.filter((f) => f.level === l).length;
  console.log(
    `\nModules: ${modules.join(", ")}. ${projects.length} projects scanned: ${n("high")} high, ${n("medium")} medium, ${n("low")} low.`,
  );
}
if (args.includes("--strict") && unique.some((f) => f.level === "high")) process.exit(1);
